// Read-only research report. Student matching and raw answer records are unchanged.
import {fetchCohortJSON} from './current-cohort-loader.js';
import {educationMatches,systemCohortLabels} from './system-match-metrics.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n):'Unassessed';
const host=document.getElementById('evidence-benchmark'),degree=p=>p.routes.some(r=>['college','graduate'].includes(r.key));
if(host)try{
 const[data,base]=await Promise.all([fetchCohortJSON('./evidence-benchmark-075.json.gz'),fetchCohortJSON('./current-cohort-data.json')]);if(data.baselineRunId!==base.runId)throw Error('Research baseline differs; rebuild required.');
 const labels={...systemCohortLabels,grok075:'New blind Grok holdout · 1,000'},allOffers=r=>[...r.beforeTop,...r.priorSupported,...r.afterSupported,...r.candidates,...r.withdrawn],careers=[...new Map(data.rows.flatMap(allOffers).map(p=>[p.id,p])).values()].sort((a,b)=>a.title.localeCompare(b.title));
 const changes=[['changed','Changed Top lists'],['losses','Top or degree coverage losses'],['withdrawn','Any withdrawn career claim'],['gains','Top or degree coverage gains'],['degree-below-cap','Supported degree outside Top three'],['reclassified','Retained specialist confirmation'],['lifestyle-lost','Lost Top lifestyle coverage'],['graduate-lost','Lost graduate Top'],['all','Every model'],['no-top','Still no supported Top'],['no-degree','Still no degree Top']];
 host.innerHTML=`<summary><strong>Reviewed evidence and blind holdout · research only</strong></summary><p>The original 1,000 and new blind 1,000 remain separate. Invalid answer implications are removed; narrower new items remain unknown when not stated. Live matching is unchanged.</p><div class="benchmark-controls"><label>Research cohort<select id="bench-cohort"><option value="all">All original models · 1,000</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}">${h(v)}</option>`).join('')}</select></label><label>Education<select id="bench-education">${[['all','Every education route'],['degree','Bachelor + graduate'],['college','Bachelor'],['graduate','Graduate / professional'],['program','Associate / specialist'],['apprenticeship','Apprenticeship'],['work','Learn at work']].map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Research change<select id="bench-change">${changes.map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Find model<input id="bench-query" type="search" placeholder="Name or ID"></label><label>Career<select id="bench-career"><option value="all">Every career</option>${careers.map(c=>`<option value="${h(c.id)}">${h(c.title)}</option>`).join('')}</select></label></div><div id="bench-metrics"></div><div id="bench-cohorts"></div><p id="bench-count" role="status"></p><div class="table-scroll" tabindex="0" role="region" aria-label="Reviewed evidence comparison"><table><thead><tr><th>Model and evidence</th><th>Current matcher<small>Same saved answers</small></th><th>Previous rules · 0.73<small>Research baseline</small></th><th>Corrected evidence · 0.75<small>Supported Top · first three</small></th><th>Unresolved / withdrawn<small>Never counted as Top</small></th></tr></thead><tbody id="bench-rows"></tbody></table></div><div class="pagination"><button id="bench-previous">← Previous</button><span id="bench-page" role="status"></span><button id="bench-next">Next →</button></div><details><summary>Frozen scope and limits</summary>${data.limitations.map(x=>`<p>${h(x)}</p>`).join('')}<a href="./evidence-benchmark-075.json.gz">Download decisions, answers and unknowns →</a> · <a href="./evidence-benchmark-073.json.gz">Retained previous replay →</a> · <a href="./docs/evidence-075-2026-10-21.md.html">Whole-profile protocol and findings →</a></details>`;
 const $=id=>document.getElementById(id);let page=0;const params=new URL(location.href).searchParams;$('bench-query').value=params.get('query')||'';if(labels[params.get('researchCohort')])$('bench-cohort').value=params.get('researchCohort');if(careers.some(c=>c.id===params.get('researchCareer')))$('bench-career').value=params.get('researchCareer');if($('bench-query').value||$('bench-career').value!=='all')$('bench-change').value='all';if(changes.some(([k])=>k===params.get('researchFilter')))$('bench-change').value=params.get('researchFilter');
 const bar=(label,v,b,a,n)=>`<div class="bench-measure"><b>${label}</b>${[['Current matcher',v,''],['Previous rules',b,'prior'],['Corrected evidence',a,'research']].map(([l,v,c])=>`<div><span>${l} ${v} / ${n}</span><i class="${c}" style="--bench-width:${100*v/Math.max(1,n)}%"></i></div>`).join('')}</div>`;
 function offer(p,label='Supported option'){return `<article class="bench-offer"><b><a href="../#/learn/career/${encodeURIComponent(p.id)}">${h(p.title)}</a></b><small>${h(label)} · ${h(p.routes.map(r=>r.label||r.key).join(' / '))}</small><small>First paid stage / proxy: ${money(p.budget.amount)}${Number.isFinite(p.budget.amount)?' / year':''} · ${h(p.budget.reason)}${p.budget.covers===true?' · covers reference budget':p.budget.covers===false&&Number.isFinite(p.budget.amount)?' · does not cover reference budget':''}</small>${p.id==='degree-27204100'?'<small>Composition only; conducting unassessed.</small>':''}${p.r==null?'<small>Broad-interest correlation unavailable.</small>':p.r<0?'<small>Broad-interest pattern points elsewhere · confirmation needed.</small>':''}</article>`;}
 function profile(r){if(!r.profile)return `<a href="./model-lab.html?case=${encodeURIComponent(r.id)}">Profile and original saved answers →</a>`;const p=r.profile,labels={raceEthnicity:'Race / ethnicity',school:'Current schooling and access',wellbeing:'Wellbeing and supports',strengths:'Strengths and developing areas',confidence:'Profile confidence · 1–5',education:'Education openness / aspiration',educationDescription:'Study preference · original wording',workContext:'Preferred work context',positiveTopics:'Appealing activities',negativeTopics:'Activities not enjoyed',positiveMethods:'Appealing ways of working',negativeMethods:'Ways of working not enjoyed',responsibilities:'Introductory responsibilities to explore',lifestyleChoices:'Lifestyle aspirations · 0 basic to 3 expansive',coherenceClarifications:'Pre-outcome coherence clarification'},value=k=>{const v=p[k];if(v==null)return 'Not provided';const kind=k.includes('Topics')?'topics':k.includes('Methods')?'methods':k==='responsibilities'?'responsibilities':null;if(kind)return v.map(id=>{const q=data.profileQuestions?.[kind]?.find(q=>q.id===id);return q?.activity||q?.fact||q?.title||id;}).map(h).join('<br>')||'None stated';if(Array.isArray(v))return v.map(x=>h(typeof x==='object'?JSON.stringify(x):x)).join('<br>')||'None stated';if(typeof v==='object')return h(JSON.stringify(v));return h(v);};return `<details><summary>Whole profile and structured answers</summary><p>${h(p.narrative)}</p><dl>${['age','gender','raceEthnicity','region','locale','household','school','wellbeing','motivation','strengths','confidence','exposure','education',...(p.educationDescription?['educationDescription']:[]),'workContext','constraints','positiveTopics','negativeTopics','positiveMethods','negativeMethods','responsibilities','lifestyleChoices',...(p.coherenceClarifications?['coherenceClarifications']:[])].map(k=>`<dt><strong>${h(labels[k]||k)}</strong></dt><dd>${value(k)}</dd>`).join('')}</dl><details><summary>Original 60 general-item responses and six diagnostic responses</summary><p>Frozen authored responses; 3 means unsure on the general items, 0 unknown on diagnostics. Only selected diagnostic questions affect proposed outcomes; unasked responses are unused.</p><ol>${p.official.map((v,i)=>`<li>${h(data.profileQuestions?.official?.[i]?.text||'Item '+(i+1))}: <b>${v} / 5</b></li>`).join('')}</ol>${Object.entries(p.followups).map(([id,v])=>`<p>${h(data.profileQuestions?.followups?.find(q=>q.id===id)?.text||id)}: <b>${v===0?'Unknown':v+' / 5'}</b></p>`).join('')}</details><p>Independently authored synthetic context. Qualitative text is not parsed into match evidence; strengths are not measured aptitudes.</p></details>`;}

 function evidence(r){const scopeIssue=(data.scopeReview||[]).some(x=>x.modelId===r.id);return `${scopeIssue?'<p><strong>Question-scope review:</strong> a negative contextual example withdrew earlier support. Check the broader interest evidence before treating the whole career as a poor fit.</p>':''}<details><summary>Audit · ${r.corrections.length} defining-check corrections / ${r.followups.length} targeted items</summary>${r.sourceCorrections.map(a=>`<article class="bench-offer"><b>${h(a.feature)}</b><p>${h(a.quote)}</p><small>${h(a.optionId)}: ${h(a.reason)}</small></article>`).join('')}${r.corrections.map(a=>`<p><b>${h(a.careerId)}</b> · ${h(a.questionId)}: ${h(a.status)} · ${h(a.reason||'')}<br>Missing ${h(a.features.join(', '))}</p>`).join('')}${r.followups.map(a=>`<article class="bench-offer"><b>${h(a.prompt)}</b><p>${h(a.status)} · ${a.value} / 5 (0 unknown)</p><small>${h(a.source)}</small></article>`).join('')}<p>Raw records preserved; only effective inferred support is re-evaluated. ${r.quarantinedResponses.length} old inferred follow-up responses quarantined.</p></details>`;}
 function render(){const cohort=$('bench-cohort').value,edu=$('bench-education').value,change=$('bench-change').value,career=$('bench-career').value,q=$('bench-query').value.trim().toLowerCase(),s=data.summary[cohort],scope=data.rows.filter(r=>cohort==='all'?r.cohort!=='grok075':r.cohort===cohort),pick=ps=>ps.filter(p=>educationMatches(p,edu));
 $('bench-metrics').innerHTML=bar('Supported Top',s.beforeTop,s.priorTop,s.afterTop,s.models)+bar('Bachelor / graduate Top',s.beforeDegree,s.priorDegree,s.afterDegree,s.models)+`<p><b>${s.gainedTop} gain / ${s.lostTop} lose Top; ${s.gainedDegree} gain / ${s.lostDegree} lose degree Top.</b> ${s.withdrawnClaims} career claims withdrawn; ${s.newClaims} newly supported. Degree anywhere ${s.afterAnyDegree}; ${s.afterDegreeBelowCap} outside Top three. Graduate Top ${s.priorGraduate} → ${s.afterGraduate}; lifestyle Top ${s.priorCovers} → ${s.afterCovers}.</p><p>Stages: Top ${s.priorTop} → ${s.correctedTop} → ${s.afterTop}; degree Top ${s.priorDegree} → ${s.correctedDegree} → ${s.afterDegree}. Previous rules → correction only → targeted answers. ${s.followups} items: ${s.positiveActivities} positive / ${s.unknownActivities} unknown / ${s.neutralActivities||0} neutral / ${s.negativeActivities||0} negative. New unknowns are never invented to restore counts.</p><p>Coverage totals use the selected cohort. Education, career and name filters narrow the table without reranking.</p>`;
 $('bench-cohorts').innerHTML='<div class="bench-cohorts">'+Object.entries(labels).filter(([k])=>data.summary[k]).map(([k,l])=>{const x=data.summary[k];return `<div><b>${h(l)}</b><p>Top ${x.priorTop} → ${x.afterTop}<br>Degree ${x.priorDegree} → ${x.afterDegree}<br>Graduate ${x.priorGraduate} → ${x.afterGraduate}</p></div>`;}).join('')+'</div>';
 const rs=scope.filter(r=>(change==='all'||change==='changed'&&r.changed||change==='withdrawn'&&r.withdrawn.length||change==='gains'&&(r.gainedTop||r.gainedDegree)||change==='losses'&&(r.lostTop||r.lostDegree)||change==='degree-below-cap'&&!r.afterTop.some(degree)&&r.afterSupported.some(degree)||change==='lifestyle-lost'&&r.lostCovers||change==='graduate-lost'&&r.lostGraduate||change==='reclassified'&&r.retainedSpecialistHolds.length||change==='no-top'&&!r.afterTop.length||change==='no-degree'&&!r.afterTop.some(degree))&&(!q||(r.id+' '+r.name).toLowerCase().includes(q))&&(edu==='all'||allOffers(r).some(p=>educationMatches(p,edu)))&&(career==='all'||allOffers(r).some(p=>p.id===career)));
 page=Math.min(page,Math.max(0,Math.ceil(rs.length/20)-1));$('bench-count').textContent=rs.length+' models in this research view';const list=ps=>pick(ps).map(p=>offer(p,'Supported Top')).join('')||'<p>No supported Top in this education view.</p>';
 $('bench-rows').innerHTML=rs.slice(page*20,page*20+20).map(r=>{const ids=new Set(r.afterTop.map(p=>p.id)),extras=pick(r.afterSupported.filter(p=>!ids.has(p.id)));return `<tr><th scope="row">${h(r.name)}<small>${h(r.id)} · ${h(labels[r.cohort])}</small>${profile(r)}${evidence(r)}</th><td>${list(r.beforeTop)}</td><td>${list(r.priorTop)}</td><td>${list(r.afterTop)}${extras.length?`<details><summary>${extras.length} further supported options · every education level and earnings</summary>${extras.map(p=>offer(p,'Supported alternative · outside Top three')).join('')}</details>`:''}</td><td>${pick(r.withdrawn).map(p=>offer(p,'Support withdrawn · interests need confirmation')).join('')}${r.candidates.length?`<details><summary>${r.candidates.length} partial-evidence candidates · not supported</summary>${pick(r.candidates).map(p=>offer(p,'Exploration candidate')+`<small>${p.missing.length} unresolved checks · ${p.contrary.length} contrary answers</small>`).join('')}</details>`:'No unresolved candidates in this view.'}</td></tr>`;}).join('')||'<tr><td colspan="5">No models meet these filters.</td></tr>';
 $('bench-page').textContent='Page '+(page+1)+' of '+Math.max(1,Math.ceil(rs.length/20));$('bench-previous').disabled=page===0;$('bench-next').disabled=(page+1)*20>=rs.length;
 }
 for(const id of['bench-cohort','bench-education','bench-change','bench-query','bench-career'])$(id).addEventListener(id==='bench-query'?'input':'change',()=>{page=0;render();});$('bench-previous').onclick=()=>{page--;render();};$('bench-next').onclick=()=>{page++;render();};if(location.hash==='#evidence-benchmark')host.open=true;render();
}catch(e){host.innerHTML='<summary>Evidence benchmark unavailable</summary><p>'+h(e.message)+'</p>';}
